DIR={1:(0,1,3),2:(0,-1,2),3:(0,-1,4),6:(1,0,2)}  # dr,dc,length by color

def transform(g):
    H=len(g); W=7
    out=[[0]*W for _ in range(H)]
    # find 5
    for r in range(H):
        for c in range(len(g[0])):
            if g[r][c]==5: out[0][c-8]=5; c5=c-8
    # collect shapes left of col 8: blocks at cols 0-2 and 4-6, rows in groups of 4 (3 rows + blank)
    shapes=[]
    for r0 in range(0,H,4):
        for c0 in (0,4):
            blk=[row[c0:c0+3] for row in g[r0:r0+3]]
            cols=set(x for row in blk for x in row if x)
            if cols: shapes.append((r0,c0,blk,cols.pop()))
    r,c=1,c5
    for i,(r0,c0,blk,col) in enumerate(shapes):
        dr,dc,L=DIR[col]
        for k in range(L):
            out[r][c]=col
            r+=dr; c+=dc
        r+=1; # next starts one below end cell
        dr,dc=DIR[col][0],DIR[col][1]
        r-= (dr==0)  # hmm fix below
    return out, shapes

